import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
lines = [
 "अचानक बेहोश होना? झटके आना? या कुछ पल के लिए खो जाना? ऐसे में डॉक्टर ई ई जी टेस्ट लिख सकते हैं. आज जानिए यह टेस्ट क्या है, और इसकी तैयारी कैसे करें. आखिर तक देखिए.",
 "ई ई जी यानी इलेक्ट्रो एन्सेफेलोग्राम. हमारा दिमाग छोटे छोटे बिजली के सिग्नल से काम करता है. ई ई जी इन्हीं सिग्नल को, लहरों के रूप में रिकॉर्ड करता है. इसके लिए सिर पर छोटे छोटे इलेक्ट्रोड लगाए जाते हैं.",
 "डरिए मत. यह टेस्ट बिल्कुल दर्द रहित है. शरीर में कोई करंट नहीं जाता. मशीन सिर्फ दिमाग के सिग्नल पढ़ती है.",
 "यह टेस्ट कब कराया जाता है? मिर्गी या दौरे की जांच के लिए, यही सबसे आम वजह है. बार बार बेहोशी, या अजीब दौरे. सिर की चोट के बाद. नींद की कुछ समस्याओं में. और गंभीर मरीज़ों में दिमाग की हालत समझने के लिए.",
 "तैयारी कैसे करें? एक रात पहले, या उसी दिन बाल धो लें. बालों में तेल, जेल, या कंडीशनर न लगाएं. अपनी दवाएं डॉक्टर की सलाह के अनुसार ही लें, खुद से बंद न करें. आमतौर पर खाना पीना सामान्य रहता है.",
 "कभी कभी डॉक्टर नींद वाला ई ई जी कहते हैं. इसके लिए एक रात पहले कम सोने को कहा जा सकता है. ऐसे में टेस्ट के बाद खुद गाड़ी न चलाएं, किसी को साथ लाएं.",
 "टेस्ट के दौरान आप आराम से लेटते हैं, आंखें बंद. आमतौर पर बीस से चालीस मिनट रिकॉर्डिंग होती है. आपको कुछ मिनट गहरी सांस लेने को, या चमकती लाइट देखने को कहा जा सकता है. इससे दिमाग के छुपे बदलाव दिख सकते हैं.",
 "रिपोर्ट को समझें. नॉर्मल ई ई जी का मतलब यह नहीं, कि मिर्गी नहीं है. क्योंकि दौरों के बीच दिमाग अक्सर सामान्य दिखता है. इसलिए कभी कभी दोबारा, नींद वाला, लंबा, या वीडियो ई ई जी करना पड़ता है. फैसला हमेशा डॉक्टर, मरीज़ के लक्षणों के साथ करते हैं.",
 "याद रखें, कोई भी दवा सिर्फ डॉक्टर की सलाह से ही लें. क्या आपके परिवार में किसी ने ई ई जी करवाया है? कमेंट में बताइए, और शेयर करें. और ज़्यादा जानकारी के लिए, हमारा फेसबुक पेज और यूट्यूब चैनल फॉलो करें. हेल्थ टेस्ट सिम्प्लिफाइड. ध्यान दें, यह वीडियो केवल बीमारियों और टेस्ट के बारे में सामान्य जानकारी के लिए है. जानकारी समय के साथ बदल सकती है. अपनी स्थिति को इस वीडियो से न जोड़ें. हमेशा अपने डॉक्टर से ही सलाह लें, और उन्हीं की सलाह मानें.",
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/eegr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/eeg_{i}.wav"],check=True); f=f"/tmp/eeg_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/eeg_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
